mapper.select:
SELECT p.id, p.pet_no, p.name, p.category_id, pc.name AS category_name,
       p.breed_id, pb.name AS breed_name, p.gender, p.age_month, p.weight, p.size,
       p.color, p.sterilized, p.vaccinated, p.dewormed, p.health_status,
       p.character_desc, p.cover_image, p.shelter_id, s.name AS shelter_name, s.city,
       p.status, p.view_count, p.favorite_count,
       DATE_FORMAT(p.publish_time, '%Y-%m-%d %H:%i:%s') AS publish_time,
       0 AS favorited
FROM pet p
LEFT JOIN pet_category pc ON pc.id = p.category_id AND pc.deleted = 0
LEFT JOIN pet_breed pb ON pb.id = p.breed_id AND pb.deleted = 0
INNER JOIN shelter s ON s.id = p.shelter_id AND s.deleted = 0

    p.deleted = 0
    AND p.status = #{q.status}
    AND p.category_id = #{q.categoryId}
    AND p.breed_id = #{q.breedId}
    AND p.gender = #{q.gender}
    AND p.size = #{q.size}
    AND p.age_month >= #{q.ageMin}
    AND p.age_month <= #{q.ageMax}
    AND s.city = #{q.city}
    AND p.shelter_id = #{q.shelterId}

        AND (MATCH(p.name, p.character_desc) AGAINST(#{q.keyword} IN NATURAL LANGUAGE MODE)
             OR p.name LIKE CONCAT('%', #{q.keyword}, '%'))



    ORDER BY p.view_count
    ORDER BY p.favorite_count
    ORDER BY p.age_month
    ORDER BY p.publish_time


    ASC
    DESC

, p.id DESC
